import React, { useState } from 'react';
import {
  Container,
  Box,
  Typography,
  Card,
  CardContent,
  Grid,
  TextField,
  Button,
  Stepper,
  Step,
  StepLabel,
  Radio,
  RadioGroup,
  FormControlLabel,
  FormControl,
  FormLabel,
  Divider,
  List,
  ListItem,
  ListItemText,
  ListItemAvatar,
  Avatar,
  Chip,
  IconButton,
  Paper,
  Alert,
  Collapse,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  Snackbar
} from '@mui/material';
import {
  ShoppingCart,
  CreditCard,
  LocalShipping,
  CheckCircle,
  ExpandMore,
  Add,
  Remove,
  Security,
  Verified,
  PaymentOutlined,
  CardGiftcard,
  AccountBalanceWallet
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import { useCart } from '../context/CartContext';

const CheckoutPage = () => {
  const navigate = useNavigate();
  const {
    cartItems,
    updateQuantity,
    getCartSubtotal,
    getCartTax,
    getShippingCost,
    getCartTotalWithShipping,
    getCartCount,
    clearCart
  } = useCart();
  
  const [activeStep, setActiveStep] = useState(0);
  const [paymentMethod, setPaymentMethod] = useState('credit-card');
  const [shippingMethod, setShippingMethod] = useState('standard');
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });

  const [shippingInfo, setShippingInfo] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    address: '',
    city: '',
    state: '',
    zipCode: '',
    country: ''
  });

  const [paymentInfo, setPaymentInfo] = useState({
    cardNumber: '',
    expiryDate: '',
    cvv: '',
    cardName: ''
  });

  const steps = ['Shipping Information', 'Payment Details', 'Review & Place Order'];

  const shippingOptions = [
    { id: 'standard', name: 'Standard Shipping', price: 9.99, time: '5-7 business days' },
    { id: 'express', name: 'Express Shipping', price: 19.99, time: '2-3 business days' },
    { id: 'overnight', name: 'Overnight Shipping', price: 39.99, time: '1 business day' }
  ];

  const paymentMethods = [
    { id: 'credit-card', name: 'Credit/Debit Card', icon: <CreditCard /> },
    { id: 'paypal', name: 'PayPal', icon: <PaymentOutlined /> },
    { id: 'apple-pay', name: 'Apple Pay', icon: <AccountBalanceWallet /> },
    { id: 'gift-card', name: 'Gift Card', icon: <CardGiftcard /> }
  ];

  // Use cart context functions instead of local calculations
  const subtotal = getCartSubtotal();
  const tax = getCartTax();
  const shipping = getShippingCost(shippingMethod);
  const total = getCartTotalWithShipping(shippingMethod);

  const handleQuantityChange = (cartId, change) => {
    const item = cartItems.find(item => item.cartId === cartId);
    if (item) {
      const newQuantity = item.quantity + change;
      if (newQuantity > 0) {
        updateQuantity(cartId, newQuantity);
      }
    }
  };

  const handleShippingInfoChange = (field, value) => {
    setShippingInfo(prev => ({ ...prev, [field]: value }));
  };

  const handlePaymentInfoChange = (field, value) => {
    setPaymentInfo(prev => ({ ...prev, [field]: value }));
  };

  const handleNext = () => {
    if (activeStep < steps.length - 1) {
      setActiveStep(prev => prev + 1);
    }
  };

  const handleBack = () => {
    if (activeStep > 0) {
      setActiveStep(prev => prev - 1);
    }
  };

  const handlePlaceOrder = () => {
    // Simulate order placement
    setSnackbar({
      open: true,
      message: 'Order placed successfully!',
      severity: 'success'
    });
    
    // Clear the cart after successful order
    clearCart();
    
    setTimeout(() => {
      navigate('/orders');
    }, 2000);
  };

  const renderShippingForm = () => (
    <Card>
      <CardContent>
        <Typography variant="h6" gutterBottom>
          Shipping Information
        </Typography>
        <Grid container spacing={3}>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="First Name"
              value={shippingInfo.firstName}
              onChange={(e) => handleShippingInfoChange('firstName', e.target.value)}
              required
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Last Name"
              value={shippingInfo.lastName}
              onChange={(e) => handleShippingInfoChange('lastName', e.target.value)}
              required
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Email"
              type="email"
              value={shippingInfo.email}
              onChange={(e) => handleShippingInfoChange('email', e.target.value)}
              required
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Phone"
              value={shippingInfo.phone}
              onChange={(e) => handleShippingInfoChange('phone', e.target.value)}
              required
            />
          </Grid>
          <Grid item xs={12}>
            <TextField
              fullWidth
              label="Address"
              value={shippingInfo.address}
              onChange={(e) => handleShippingInfoChange('address', e.target.value)}
              required
            />
          </Grid>
          <Grid item xs={12} sm={4}>
            <TextField
              fullWidth
              label="City"
              value={shippingInfo.city}
              onChange={(e) => handleShippingInfoChange('city', e.target.value)}
              required
            />
          </Grid>
          <Grid item xs={12} sm={4}>
            <TextField
              fullWidth
              label="State"
              value={shippingInfo.state}
              onChange={(e) => handleShippingInfoChange('state', e.target.value)}
              required
            />
          </Grid>
          <Grid item xs={12} sm={4}>
            <TextField
              fullWidth
              label="ZIP Code"
              value={shippingInfo.zipCode}
              onChange={(e) => handleShippingInfoChange('zipCode', e.target.value)}
              required
            />
          </Grid>
        </Grid>

        {/* Shipping Options */}
        <Box sx={{ mt: 4 }}>
          <Typography variant="h6" gutterBottom>
            Shipping Method
          </Typography>
          <FormControl component="fieldset">
            <RadioGroup
              value={shippingMethod}
              onChange={(e) => setShippingMethod(e.target.value)}
            >
              {shippingOptions.map((option) => (
                <FormControlLabel
                  key={option.id}
                  value={option.id}
                  control={<Radio />}
                  label={
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', width: '100%', minWidth: 300 }}>
                      <Box>
                        <Typography fontWeight="medium">{option.name}</Typography>
                        <Typography variant="body2" color="text.secondary">
                          {option.time}
                        </Typography>
                      </Box>
                      <Typography fontWeight="bold">
                        ${option.price.toFixed(2)}
                      </Typography>
                    </Box>
                  }
                  sx={{ mb: 1, border: '1px solid #e0e0e0', borderRadius: 1, p: 1, m: 0.5 }}
                />
              ))}
            </RadioGroup>
          </FormControl>
        </Box>
      </CardContent>
    </Card>
  );

  const renderPaymentForm = () => (
    <Card>
      <CardContent>
        <Typography variant="h6" gutterBottom>
          Payment Method
        </Typography>
        
        <FormControl component="fieldset" sx={{ mb: 3 }}>
          <RadioGroup
            value={paymentMethod}
            onChange={(e) => setPaymentMethod(e.target.value)}
          >
            {paymentMethods.map((method) => (
              <FormControlLabel
                key={method.id}
                value={method.id}
                control={<Radio />}
                label={
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    {method.icon}
                    <Typography>{method.name}</Typography>
                  </Box>
                }
                sx={{ mb: 1 }}
              />
            ))}
          </RadioGroup>
        </FormControl>

        {paymentMethod === 'credit-card' && (
          <Grid container spacing={3}>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Card Number"
                value={paymentInfo.cardNumber}
                onChange={(e) => handlePaymentInfoChange('cardNumber', e.target.value)}
                placeholder="1234 5678 9012 3456"
                inputProps={{ maxLength: 19 }}
                required
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Expiry Date"
                value={paymentInfo.expiryDate}
                onChange={(e) => handlePaymentInfoChange('expiryDate', e.target.value)}
                placeholder="MM/YY"
                inputProps={{ maxLength: 5 }}
                required
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="CVV"
                value={paymentInfo.cvv}
                onChange={(e) => handlePaymentInfoChange('cvv', e.target.value)}
                placeholder="123"
                inputProps={{ maxLength: 4 }}
                required
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Cardholder Name"
                value={paymentInfo.cardName}
                onChange={(e) => handlePaymentInfoChange('cardName', e.target.value)}
                required
              />
            </Grid>
          </Grid>
        )}

        {paymentMethod !== 'credit-card' && (
          <Alert severity="info">
            You will be redirected to {paymentMethods.find(m => m.id === paymentMethod)?.name} to complete your payment.
          </Alert>
        )}

        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 3, p: 2, bgcolor: 'grey.50', borderRadius: 1 }}>
          <Security color="success" />
          <Typography variant="body2">
            Your payment information is secure and encrypted
          </Typography>
        </Box>
      </CardContent>
    </Card>
  );

  const renderOrderReview = () => (
    <Card>
      <CardContent>
        <Typography variant="h6" gutterBottom>
          Order Summary
        </Typography>
        
        {/* Shipping Information Review */}
        <Accordion defaultExpanded>
          <AccordionSummary expandIcon={<ExpandMore />}>
            <Typography fontWeight="medium">Shipping Information</Typography>
          </AccordionSummary>
          <AccordionDetails>
            <Typography variant="body2">
              {shippingInfo.firstName} {shippingInfo.lastName}<br />
              {shippingInfo.address}<br />
              {shippingInfo.city}, {shippingInfo.state} {shippingInfo.zipCode}<br />
              {shippingInfo.email}<br />
              {shippingInfo.phone}
            </Typography>
          </AccordionDetails>
        </Accordion>

        {/* Payment Method Review */}
        <Accordion>
          <AccordionSummary expandIcon={<ExpandMore />}>
            <Typography fontWeight="medium">Payment Method</Typography>
          </AccordionSummary>
          <AccordionDetails>
            <Typography variant="body2">
              {paymentMethods.find(m => m.id === paymentMethod)?.name}
              {paymentMethod === 'credit-card' && paymentInfo.cardNumber && (
                <span> ending in {paymentInfo.cardNumber.slice(-4)}</span>
              )}
            </Typography>
          </AccordionDetails>
        </Accordion>

        {/* Shipping Method Review */}
        <Accordion>
          <AccordionSummary expandIcon={<ExpandMore />}>
            <Typography fontWeight="medium">Shipping Method</Typography>
          </AccordionSummary>
          <AccordionDetails>
            <Typography variant="body2">
              {shippingOptions.find(s => s.id === shippingMethod)?.name} - $
              {shippingOptions.find(s => s.id === shippingMethod)?.price.toFixed(2)}
            </Typography>
          </AccordionDetails>
        </Accordion>
      </CardContent>
    </Card>
  );

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      <Typography variant="h4" fontWeight="bold" gutterBottom>
        Checkout
      </Typography>

      <Stepper activeStep={activeStep} sx={{ mb: 4 }}>
        {steps.map((label) => (
          <Step key={label}>
            <StepLabel>{label}</StepLabel>
          </Step>
        ))}
      </Stepper>

      <Grid container spacing={4}>
        {/* Main Content */}
        <Grid item xs={12} md={8}>
          {activeStep === 0 && renderShippingForm()}
          {activeStep === 1 && renderPaymentForm()}
          {activeStep === 2 && renderOrderReview()}

          {/* Navigation Buttons */}
          <Box sx={{ display: 'flex', justifyContent: 'space-between', mt: 3 }}>
            <Button
              onClick={handleBack}
              disabled={activeStep === 0}
              variant="outlined"
            >
              Back
            </Button>
            <Button
              onClick={activeStep === steps.length - 1 ? handlePlaceOrder : handleNext}
              variant="contained"
              size="large"
              startIcon={activeStep === steps.length - 1 ? <CheckCircle /> : null}
            >
              {activeStep === steps.length - 1 ? 'Place Order' : 'Continue'}
            </Button>
          </Box>
        </Grid>

        {/* Order Summary Sidebar */}
        <Grid item xs={12} md={4}>
          <Card sx={{ position: 'sticky', top: 20 }}>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Order Summary
              </Typography>

              {/* Cart Items */}
              <List sx={{ mb: 2 }}>
                {cartItems.map((item) => (
                  <ListItem key={item.cartId} sx={{ px: 0 }}>
                    <ListItemAvatar>
                      <Avatar
                        src={item.image}
                        alt={item.name}
                        variant="rounded"
                        sx={{ width: 56, height: 56 }}
                      />
                    </ListItemAvatar>
                    <ListItemText
                      primary={
                        <Typography variant="body2" fontWeight="medium">
                          {item.name}
                        </Typography>
                      }
                      secondary={
                        <Box>
                          <Typography variant="caption" color="text.secondary">
                            Size: {item.size}, Color: {item.color}
                          </Typography>
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 0.5 }}>
                            <IconButton 
                              size="small" 
                              onClick={() => handleQuantityChange(item.id, -1)}
                              disabled={item.quantity <= 1}
                            >
                              <Remove fontSize="small" />
                            </IconButton>
                            <Typography variant="body2">{item.quantity}</Typography>
                            <IconButton 
                              size="small" 
                              onClick={() => handleQuantityChange(item.id, 1)}
                            >
                              <Add fontSize="small" />
                            </IconButton>
                            <Typography variant="body2" fontWeight="bold" sx={{ ml: 'auto' }}>
                              ${(item.price * item.quantity).toFixed(2)}
                            </Typography>
                          </Box>
                        </Box>
                      }
                    />
                  </ListItem>
                ))}
              </List>

              <Divider sx={{ my: 2 }} />

              {/* Price Breakdown */}
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                  <Typography>Subtotal</Typography>
                  <Typography>${calculateSubtotal().toFixed(2)}</Typography>
                </Box>
                <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                  <Typography>Shipping</Typography>
                  <Typography>${calculateShipping().toFixed(2)}</Typography>
                </Box>
                <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                  <Typography>Tax</Typography>
                  <Typography>${calculateTax().toFixed(2)}</Typography>
                </Box>
                <Divider />
                <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                  <Typography variant="h6" fontWeight="bold">
                    Total
                  </Typography>
                  <Typography variant="h6" fontWeight="bold" color="primary">
                    ${calculateTotal().toFixed(2)}
                  </Typography>
                </Box>
              </Box>

              {/* Security Badge */}
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 3, p: 2, bgcolor: 'success.light', borderRadius: 1 }}>
                <Verified color="success" />
                <Typography variant="body2" color="success.dark">
                  SSL Secure Checkout
                </Typography>
              </Box>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Snackbar */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={3000}
        onClose={() => setSnackbar({ ...snackbar, open: false })}
      >
        <Alert severity={snackbar.severity} onClose={() => setSnackbar({ ...snackbar, open: false })}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Container>
  );
};

export default CheckoutPage;
